// Block (composition) — an ORDERED list whose order is the value: rows are added, removed, moved
// and edited in place. GridList owns the collection and the drag/keyboard reorder behaviour
// (react-aria's `useDragAndDrop`), Button owns the affordances, Stack owns arrangement. This Block
// defines no tokens.
//
// Distinct from the two units it is most often mistaken for, and the distinction is what the list
// holds rather than how it looks:
//   • `MultiSelectList` picks a SUBSET of options that already exist. It cannot mint a value and has
//     no order — a filter or an audience.
//   • `TagGroup` displays values and can remove them. It cannot add or move one.
// This is for a sequence the author AUTHORS: the items are theirs, and an item's POSITION carries
// meaning the item itself does not state. A stacking order, a ladder of named rungs, a series
// order. Moving row 3 above row 2 is the edit.
//
// The row's editor is the caller's (`renderItem`), for the same reason `DataTable` takes a cell
// renderer: the sequences that need this are a text name, a number and a pick-from-a-roster, and a
// Block that shipped one of the three would be the wrong one two times out of three.
//
// Panel posture: it sits inside a page, so width comes from the parent (block-contract §1b).
import { useId, type ReactNode, type Ref } from "react";
import { useDragAndDrop } from "react-aria-components";
import type { Key } from "react-aria-components";
import { Menu12, Plus, X } from "../components/icons";
import { Button } from "../components/Button";
import { GridList, GridListItem } from "../components/GridList";
import { DropIndicator } from "../components/DropIndicator";
import { Stack } from "../layouts/Stack";
import "./SequenceEditor.css";

export interface SequenceEditorItem {
  /** Stable across an edit to the row's value — the row is a slot, not its contents. Renaming a
   *  rung must not look like a delete and an insert, or the row loses focus mid-keystroke. */
  id: string;
  /** What the row holds, and the row's accessible name. */
  value: string;
  /** What this position DERIVES — the z-index the order produced, the px the rung landed on.
   *  Read-only: it is the consequence of the order, so it moves when the row moves. */
  hint?: ReactNode;
}

export interface SequenceEditorProps {
  /** The sequence, in order. Controlled: every mutation comes back through `onChange`. */
  items: SequenceEditorItem[];
  /** The whole next sequence, after a move or a removal. */
  onChange: (items: SequenceEditorItem[]) => void;
  /** The row's editor. Omit for a sequence that is ordered but not edited in place. */
  renderItem?: (item: SequenceEditorItem) => ReactNode;
  /** Adds a row. Omit and no add button renders — a fixed-length sequence that only reorders. */
  onAdd?: () => void;
  /** Add button text. */
  addLabel?: string;
  /** A Panel never defaults a page title (block-contract §1b). */
  heading?: string;
  /** Accessible name for the list when there is no visible `heading`. */
  "aria-label"?: string;
  /** Shown when the sequence is empty. */
  emptyMessage?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function SequenceEditor({
  items,
  onChange,
  renderItem,
  onAdd,
  addLabel = "Add",
  heading,
  "aria-label": ariaLabel,
  emptyMessage = "Nothing here yet.",
  className,
  ref,
}: SequenceEditorProps) {
  const headingId = useId();

  // The reorder itself. RAC reports the drop as a key and a side; the array move is ours because
  // the array IS the value — a list-data hook would hold a second copy of it, and the copy is what
  // goes stale when the caller's config is edited from anywhere else (a brand switch, a paste).
  const move = (
    targetKey: string,
    movedKeys: Iterable<Key>,
    before: boolean,
  ) => {
    const moved = [...movedKeys].map(String);
    const rest = items.filter((i) => !moved.includes(i.id));
    const picked = items.filter((i) => moved.includes(i.id));
    const at = rest.findIndex((i) => i.id === targetKey);
    // The target may itself be one of the moved rows, in which case it is no longer in `rest` and
    // `findIndex` answers -1. Dropping on yourself is a no-op, not an insert at the head.
    if (at < 0) return;
    onChange([
      ...rest.slice(0, before ? at : at + 1),
      ...picked,
      ...rest.slice(before ? at : at + 1),
    ]);
  };

  const { dragAndDropHooks } = useDragAndDrop({
    getItems: (keys) =>
      [...keys].map((key) => ({
        "text/plain": items.find((i) => i.id === key)?.value ?? "",
      })),
    // `onReorder`, not `onMove`. Both fire for a within-list move, but `onMove` is the handler
    // for moving BETWEEN collections, and giving it makes every row an "insert into" drop target
    // as well: the keyboard cycle then offers "Drop on sticky" between the two inserts, and
    // dropping there calls nothing at all. Measured — the row order did not move.
    onReorder: (e) =>
      move(String(e.target.key), e.keys, e.target.dropPosition === "before"),
    renderDropIndicator: (target) => <DropIndicator target={target} />,
  });

  return (
    <Stack
      as="section"
      ref={ref}
      // `medium`, not `small`: at `small` the heading sat the same distance from the first row as
      // the rows sit from each other, so it read as a member of the rhythm rather than as its
      // heading. Judged on this Block's own render — `block-contract.md` §4a retracted a tier-wide
      // rule for exactly this and records a counter-case, so nothing here generalises.
      gap="medium"
      aria-labelledby={heading ? headingId : undefined}
      aria-label={heading ? undefined : (ariaLabel ?? "Sequence")}
      className={
        className ? `sd-sequence-editor ${className}` : "sd-sequence-editor"
      }
    >
      {heading && (
        <>
          <h2
            id={headingId}
            className="sd-sequence-editor__heading sd-type-title-medium"
          >
            {heading}
          </h2>
        </>
      )}
      <GridList
        aria-label={heading ?? ariaLabel ?? "Sequence"}
        items={items}
        dragAndDropHooks={dragAndDropHooks}
        renderEmptyState={() => emptyMessage}
      >
        {(item) => (
          <GridListItem
            id={item.id}
            textValue={item.value}
            trailing={
              <span className="sd-sequence-editor__trailing">
                {item.hint !== undefined && (
                  // A readout derived from the row's value: supporting text about that value (type
                  // row 2), so `caption`, which already reads quieter than the row's `body`.
                  <span className="sd-sequence-editor__hint sd-type-caption-medium">
                    {item.hint}
                  </span>
                )}
                <Button
                  variant="ghost"
                  size="small"
                  aria-label={`Remove ${item.value}`}
                  onPress={() =>
                    onChange(items.filter((i) => i.id !== item.id))
                  }
                >
                  <X aria-hidden />
                </Button>
              </span>
            }
          >
            {/* `slot="drag"` is RAC's own drag affordance, and it is the KEYBOARD path too:
                  it takes focus, Enter picks the row up, the arrows move it, Enter drops it.
                  Pointer-only reordering would put this whole family behind a mouse. */}
            <Button
              slot="drag"
              variant="ghost"
              size="small"
              aria-label={`Reorder ${item.value}`}
              className="sd-sequence-editor__handle"
            >
              <Menu12 aria-hidden />
            </Button>
            <span className="sd-sequence-editor__field">
              {renderItem ? renderItem(item) : item.value}
            </span>
          </GridListItem>
        )}
      </GridList>
      {onAdd && (
        <Button variant="secondary" onPress={onAdd}>
          <Plus aria-hidden />
          {addLabel}
        </Button>
      )}
    </Stack>
  );
}

.sd-sequence-editor {
  width: 100%;
}

.sd-sequence-editor__heading {
  margin: 0;
}

/* The row's editor takes the slack, so a text field and a select line up down the column whatever
   the row holds. `min-width: 0` because a field inside a flex row refuses to shrink below its
   intrinsic width otherwise, and the trailing readout is the thing that gets pushed off. */
.sd-sequence-editor__field {
  flex: 1;
  min-width: 0;
}

.sd-sequence-editor__handle {
  flex: none;
  cursor: grab;
}

.sd-sequence-editor__trailing {
  display: flex;
  align-items: center;
  gap: var(--sd-space-x-small);
}

/* What the position derived. It reads as subordinate through its TYPE — `label-small` against the
   row's `body-medium`, the contrastive rung `naming-convention.md` § Typography sanctions — and not
   through colour: a Block owns no look, so a muted foreground here would be the Block choosing a
   colour that belongs to GridList or to Sys (block-contract §3, §5). GridList does own a muted
   treatment, on its `description` slot, which renders under the title rather than at the row end.
   If the size contrast turns out to be too little, that is a gap in GridList's trailing slot to
   close there — not a colour to add here. */
.sd-sequence-editor__hint {
  font-variant-numeric: tabular-nums;
}
